import{_ as t,o as a,c as e,af as o}from"./chunks/framework.B28LkSoM.js";const g=JSON.parse('{"title":"SQL分类与数据库操作","description":"承接上一篇。先讲清 SQL 是什么、四大分类（DDL/DML/DQL/DCL）各自管什么，再把 DDL 的数据库这一层练完——查询所有库、查询当前库、切换、创建（if not exists + default charset utf8mb4）、删除（if exists）五条语法，附本机实测的 1007/1008 报错原文；最后说命令行客户端的三个痛点，引出图形化工具 DataGrip 的安装与连接配置","frontmatter":{"title":"SQL分类与数据库操作","published":"2026-09-29T00:00:00.000Z","description":"承接上一篇。先讲清 SQL 是什么、四大分类（DDL/DML/DQL/DCL）各自管什么，再把 DDL 的数据库这一层练完——查询所有库、查询当前库、切换、创建（if not exists + default charset utf8mb4）、删除（if exists）五条语法，附本机实测的 1007/1008 报错原文；最后说命令行客户端的三个痛点，引出图形化工具 DataGrip 的安装与连接配置","tags":["JavaWeb","MySQL","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-41-sql-categories.webp","order":41,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/41-SQL分类与数据库操作.md","filePath":"posts/学习文档/JavaWeb学习笔记/41-SQL分类与数据库操作.md"}'),n={name:"posts/学习文档/JavaWeb学习笔记/41-SQL分类与数据库操作.md"};function d(i,s,r,c,l,p){return a(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...s[0]||(s[0]=[o(`<p><a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇</a>把 MySQL 装好、也连上了，但连上去之后呢？界面上只有一个 <code>mysql&gt;</code> 提示符，<strong>得会&quot;说话&quot;才行</strong>——这门和数据库打交道的语言就是 SQL。</p><p>这一篇解决两件事：<strong>SQL 都有哪些种类</strong>（PPT 第 19-23 页的分类与导航），以及<strong>第一类 DDL 里&quot;数据库&quot;这一层怎么操作</strong>（PPT 第 24-25 页）。最后 PPT 第 26-28 页会解释为什么企业里更爱用图形化工具，并介绍 DataGrip。</p><h2 id="sql-是什么、分成哪四类-ppt-第-19-21-页" tabindex="-1">SQL 是什么、分成哪四类（PPT 第 19-21 页） <a class="header-anchor" href="#sql-是什么、分成哪四类-ppt-第-19-21-页" aria-label="Permalink to &quot;SQL 是什么、分成哪四类（PPT 第 19-21 页）&quot;">​</a></h2><p>PPT 第 19-20 页是章节导航（&quot;SQL 语句 02&quot;），第 21 页给出定义：</p><blockquote><p><strong>SQL：一门操作关系型数据库的编程语言，定义操作所有关系型数据库的统一标准。</strong></p></blockquote><p>注意两点：&quot;<strong>所有</strong>关系型数据库&quot;和&quot;<strong>统一标准</strong>&quot;——这也是 <a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇</a>里说的那句话的延伸：MySQL 里学的 SQL，换到 Oracle、PostgreSQL 上大体通用。SQL 按用途分成四类：</p><table tabindex="0"><thead><tr><th>分类</th><th>全称</th><th>说明（PPT 第 21 页原文）</th></tr></thead><tbody><tr><td><strong>DDL</strong></td><td>Data <strong>Definition</strong> Language</td><td><strong>数据定义语言</strong>，用来定义数据库对象（<strong>数据库，表，字段</strong>）</td></tr><tr><td><strong>DML</strong></td><td>Data <strong>Manipulation</strong> Language</td><td><strong>数据操作语言</strong>，用来对数据库<strong>表中的数据进行增删改</strong></td></tr><tr><td><strong>DQL</strong></td><td>Data <strong>Query</strong> Language</td><td><strong>数据查询语言</strong>，用来<strong>查询</strong>数据库中表的<strong>记录</strong></td></tr><tr><td><strong>DCL</strong></td><td>Data <strong>Control</strong> Language</td><td><strong>数据控制语言</strong>，用来<strong>创建数据库用户、控制数据库的访问权限</strong></td></tr></tbody></table><p>这张表要按&quot;<strong>操作对象</strong>&quot;来记，最不容易混：</p><table tabindex="0"><thead><tr><th>分类</th><th>操作对象</th><th>典型关键字</th><th>本课程在哪讲</th></tr></thead><tbody><tr><td><strong>DDL</strong></td><td>数据库、表、字段（<strong>结构</strong>）</td><td><code>create</code> / <code>drop</code> / <code>alter</code> / <code>show</code></td><td>本篇（数据库）+ <a href="/posts/编程学习/javaweb学习笔记/42-ddl表结构-创建与约束/">42</a>-44（表结构）</td></tr><tr><td><strong>DML</strong></td><td>表里的<strong>数据</strong>（增删改）</td><td><code>insert</code> / <code>update</code> / <code>delete</code></td><td>45 篇</td></tr><tr><td><strong>DQL</strong></td><td>表里的<strong>记录</strong>（查）</td><td><code>select</code></td><td>46-48 篇</td></tr><tr><td><strong>DCL</strong></td><td>用户与权限</td><td><code>grant</code> / <code>revoke</code> 等</td><td>本课程不展开</td></tr></tbody></table><p>PPT 第 21 页还配了一张架构图，把这些分类&quot;贴&quot;到了<a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇</a>那张数据模型图上：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 ──► 数据库服务器</span></span>
<span class="line"><span>             ├── DBMS          ← DML / DQL 在这里作用于&quot;表里的数据&quot;</span></span>
<span class="line"><span>             ├── 数据库1        ← DDL 作用在&quot;库&quot;这一层</span></span>
<span class="line"><span>             │     ├── 表1      ← DDL 作用在&quot;表&quot;这一层</span></span>
<span class="line"><span>             │     └── 表2</span></span>
<span class="line"><span>             └── 数据库2</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p>一句话区分 DDL 与 DML/DQL：<strong>DDL 动的是&quot;结构&quot;（有什么库、有什么表、表里有哪些字段），DML/DQL 动的是&quot;内容&quot;（表里存了什么数据）</strong>。所以后面建表、改字段用 DDL；插数据、改数据用 DML；查数据用 DQL。</p></div><h2 id="ddl-数据库-五条语法-ppt-第-24-页" tabindex="-1">DDL-数据库：五条语法（PPT 第 24 页） <a class="header-anchor" href="#ddl-数据库-五条语法-ppt-第-24-页" aria-label="Permalink to &quot;DDL-数据库：五条语法（PPT 第 24 页）&quot;">​</a></h2><p>PPT 第 22-23 页是两张导航页，展示 DDL 被拆成三块：<strong>数据库</strong>（本篇）、<strong>表结构-创建</strong>（<a href="/posts/编程学习/javaweb学习笔记/42-ddl表结构-创建与约束/">42 篇</a>）、<strong>表结构-查询、修改、删除</strong>（44 篇）。先看第一块——<strong>数据库这一层的五条语法</strong>（PPT 第 24 页原文，课程的 <code>SQL脚本.sql</code> 与它一致）：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查询所有数据库</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查询当前数据库</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 使用/切换数据库</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 数据库名;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 创建数据库</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [if not exists] 数据库名 [default charset utf8mb4];</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 删除数据库</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">drop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [if exists] 数据库名;</span></span></code></pre></div><p>PPT 把这一页的顺序总结成&quot;<strong>查询 – 使用 – 创建 – 删除</strong>&quot;，正好是日常操作的顺序（先看看有什么，再切过去用，要新建就建，不要了就删）。五条逐条拆开：</p><table tabindex="0"><thead><tr><th>语句</th><th>作用</th><th>要点</th></tr></thead><tbody><tr><td><code>show databases;</code></td><td>列出<strong>当前服务器上所有</strong>数据库</td><td>系统库（<code>information_schema</code>、<code>mysql</code>、<code>performance_schema</code>、<code>sys</code>）也会一起列出来</td></tr><tr><td><code>select database();</code></td><td>显示<strong>当前正在使用</strong>的数据库</td><td>注意是带括号的函数写法；还没 <code>use</code> 过时结果是 <code>NULL</code></td></tr><tr><td><code>use 数据库名;</code></td><td><strong>切换</strong>当前数据库</td><td>命令行客户端只回一行 <code>Database changed</code>——它不会告诉你现在到底是哪个库，所以切换后用 <code>select database()</code> 确认</td></tr><tr><td><code>create database [if not exists] 数据库名 [default charset utf8mb4];</code></td><td><strong>创建</strong>数据库</td><td><code>if not exists</code> 让&quot;库已存在&quot;时不报错；<code>default charset</code> 指定字符集</td></tr><tr><td><code>drop database [if exists] 数据库名;</code></td><td><strong>删除</strong>数据库</td><td>⚠️ 库里的<strong>所有表和数据都会一起删掉</strong>；<code>if exists</code> 让&quot;库不存在&quot;时不报错</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">警告</p><p>删除数据库是<strong>不可逆</strong>操作：库删了，里面的表、表里的数据全没了。练习时删的是自己建的练习库没问题，<strong>生产环境删库之前一定要确认备份</strong>。</p></div><h3 id="实测-报错长什么样-1007-1008" tabindex="-1">实测：报错长什么样（1007 / 1008） <a class="header-anchor" href="#实测-报错长什么样-1007-1008" aria-label="Permalink to &quot;实测：报错长什么样（1007 / 1008）&quot;">​</a></h3><p>课程源码 <code>SQL脚本.sql</code> 里最朴素的写法是 <code>create database db03;</code> 和 <code>drop database db03;</code>。**本机实测（MySQL 9.0.1）**把重复创建与删除不存在库这两种情况都跑了一遍：</p><table tabindex="0"><thead><tr><th>操作</th><th>结果</th></tr></thead><tbody><tr><td><code>create database db01;</code>（已存在）</td><td><code>ERROR 1007 (HY000): Can&#39;t create database &#39;db01&#39;; database exists</code></td></tr><tr><td><code>drop database db_not_exist;</code>（不存在）</td><td><code>ERROR 1008 (HY000): Can&#39;t drop database &#39;db_not_exist&#39;; database doesn&#39;t exist</code></td></tr><tr><td><code>create database if not exists db01;</code></td><td><code>Query OK, 0 rows affected, 1 warning (0.00 sec)</code>（不报错，只给一条 warning）</td></tr><tr><td><code>drop database if exists db_not_exist;</code></td><td><code>Query OK, 0 rows affected, 1 warning (0.00 sec)</code></td></tr></tbody></table><p><img src="https://img.tsh520.cn/file/blog/article/26-%E5%91%BD%E4%BB%A4%E8%A1%8C%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%93%8D%E4%BD%9C.jpg" alt="命令行客户端的数据库操作"><em>图：PPT 第 26 页——命令行客户端里的实操：<code>show databases</code> 列出了 6 个库（<code>db01</code>、<code>db02</code> 加四个系统库），<code>drop database db03</code> 第一次 <code>Query OK</code>、再执行一次就报 <code>ERROR 1008 (HY000): Can&#39;t drop database &#39;db03&#39;; database doesn&#39;t exist</code>，而加上 <code>if exists</code> 之后变成 <code>Query OK, 0 rows affected, 1 warning</code>——这就是 if exists / if not exists 存在的意义</em></p><h2 id="两个注意点-ppt-第-24-25-页" tabindex="-1">两个注意点（PPT 第 24-25 页） <a class="header-anchor" href="#两个注意点-ppt-第-24-25-页" aria-label="Permalink to &quot;两个注意点（PPT 第 24-25 页）&quot;">​</a></h2><p>PPT 第 24 页在语法下面写了&quot;注意&quot;，第 25 页用问答的形式又把它们问了一遍。</p><h3 id="注意一-database-可以换成-schema" tabindex="-1">注意一：<code>database</code> 可以换成 <code>schema</code> <a class="header-anchor" href="#注意一-database-可以换成-schema" aria-label="Permalink to &quot;注意一：\`database\` 可以换成 \`schema\`&quot;">​</a></h3><blockquote><p>上述语法中的 <strong>database，也可以替换成 schema</strong>。如：<code>create schema db01;</code></p></blockquote><p>也就是说 <code>create database db01;</code> 和 <code>create schema db01;</code> 是一回事（schema 是&quot;模式&quot;的叫法，很多数据库产品用这个词）。课程里统一用 <code>database</code>，<code>SQL脚本.sql</code> 里也是 <code>database</code>，看别人代码时见到 <code>schema</code> 别不认识。</p><h3 id="注意二-mysql-8-默认字符集是-utf8mb4" tabindex="-1">注意二：MySQL 8 默认字符集是 utf8mb4 <a class="header-anchor" href="#注意二-mysql-8-默认字符集是-utf8mb4" aria-label="Permalink to &quot;注意二：MySQL 8 默认字符集是 utf8mb4&quot;">​</a></h3><blockquote><p><strong>MySQL8 版本中，默认字符集为 utf8mb4。</strong></p></blockquote><p>所以严格来说 <code>default charset utf8mb4</code> 是&quot;<strong>显式写清楚</strong>&quot;的写法——不写也一样是 utf8mb4。但<strong>建议写</strong>：一是意图明确（别人一眼看出这个库用什么字符集），二是万一环境不同、默认值不一样，也不会踩到 <a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇</a>那个 1366 的坑。</p><p>下面是 PPT 第 25 页的两问：</p><table tabindex="0"><thead><tr><th>问题（PPT 第 25 页）</th><th>答案</th></tr></thead><tbody><tr><td><strong>同一个数据库服务器中，数据库的名字是否可以相同？</strong></td><td><strong>不可以</strong>（重名会报 <code>ERROR 1007 ... database exists</code>，也就是上面实测的那条）</td></tr><tr><td><strong>MySQL 8 版本默认的字符集是什么？</strong></td><td><strong>utf8mb4</strong>（对应写法 <code>default charset utf8mb4</code>）</td></tr></tbody></table><h2 id="命令行客户端的三个痛点-ppt-第-26-页" tabindex="-1">命令行客户端的三个痛点（PPT 第 26 页） <a class="header-anchor" href="#命令行客户端的三个痛点-ppt-第-26-页" aria-label="Permalink to &quot;命令行客户端的三个痛点（PPT 第 26 页）&quot;">​</a></h2><p>PPT 第 26 页把命令行客户端的问题列成三条：</p><table tabindex="0"><thead><tr><th>痛点（PPT 第 26 页原文）</th><th>具体表现</th></tr></thead><tbody><tr><td><strong>无提示</strong></td><td>关键字、表名、字段名全靠记，敲错了只能自己看报错</td></tr><tr><td><strong>操作繁琐</strong></td><td>想看表结构、改数据都得手敲语句，多表操作更麻烦</td></tr><tr><td><strong>无历史记录</strong></td><td>关掉窗口，之前敲过的 SQL 就找不回来了</td></tr></tbody></table><p>这三条决定了企业里日常开发的做法：<strong>用图形化客户端工具连数据库</strong>（PPT 第 26 页标题就是&quot;MySQL 客户端工具&quot;）。命令行仍然要会——服务器上排障、写脚本、临时查个数都靠它，只是不必拿它当日常主力。</p><h2 id="datagrip-图形化客户端-ppt-第-27-28-页" tabindex="-1">DataGrip：图形化客户端（PPT 第 27-28 页） <a class="header-anchor" href="#datagrip-图形化客户端-ppt-第-27-28-页" aria-label="Permalink to &quot;DataGrip：图形化客户端（PPT 第 27-28 页）&quot;">​</a></h2><p>PPT 第 27 页的原文：</p><blockquote><p><strong>介绍</strong>：DataGrip 是 <strong>JetBrains</strong> 旗下的一款数据库管理工具，是管理和开发 <strong>MySQL、Oracle、PostgreSQL</strong> 的理想解决方案。 <strong>官网</strong>：&lt;<a href="https://www.jetbrains.com/zh-cn/datagrip/" target="_blank" rel="noreferrer">https://www.jetbrains.com/zh-cn/datagrip/</a>&gt; <strong>安装</strong>：参考资料中提供的《DataGrip 安装手册》</p></blockquote><p>三个痛点它分别对应解决：<strong>有智能提示</strong>（关键字、表名、字段名、函数名边打边提示）、<strong>图形化操作</strong>（新建表、改数据点点鼠标，也能直接写 SQL 并瞬间出结果）、<strong>有历史记录</strong>（每条执行过的语句都留档，控制台日志可查）。课程用的版本是资料包里的 <code>datagrip-2024.1.1.exe</code>。</p><p>PPT 第 28 页演示的是&quot;<strong>用 DataGrip 连上 MySQL</strong>&quot;这两步。</p><p>第一步：打开 DataGrip 的 <strong>Database Explorer</strong>，点 <code>+</code> → <code>Data Source</code> → 选 <strong>MySQL</strong>：</p><p><img src="https://img.tsh520.cn/file/blog/article/27-DataGrip%E6%96%B0%E5%BB%BA%E6%95%B0%E6%8D%AE%E6%BA%90.jpg" alt="DataGrip新建数据源"><em>图：PPT 第 28 页——在 DataGrip 里新建数据源：Database Explorer 面板点 <code>+</code>，选 Data Source → MySQL（Recent 里直接就有）</em></p><p>第二步：在连接配置页填四样东西，然后下载驱动：</p><p><img src="https://img.tsh520.cn/file/blog/article/27-DataGrip%E8%BF%9E%E6%8E%A5%E9%85%8D%E7%BD%AE.jpg" alt="DataGrip连接配置"><em>图：PPT 第 28 页——DataGrip 的连接配置页：Host 填 IP 地址、Port 填端口号（本机是 localhost:3306）、User 填用户名、Password 填密码，下面的 URL 会自动拼成 <code>jdbc:mysql://localhost:3306</code>；右下方标红的位置要点一下 Download，把驱动下下来才能连通</em></p><p>对照 <a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇</a>的命令行连接，这两个界面填的其实是同一组信息：</p><table tabindex="0"><thead><tr><th>命令行参数</th><th>DataGrip 里对应的框</th></tr></thead><tbody><tr><td><code>-h</code> 后的 IP</td><td><strong>Host</strong></td></tr><tr><td><code>-P</code> 后的端口</td><td><strong>Port</strong></td></tr><tr><td><code>-u</code> 后的用户名</td><td><strong>User</strong></td></tr><tr><td><code>-p</code> 后的密码</td><td><strong>Password</strong></td></tr></tbody></table><p>连上之后，左边的 Database Explorer 会把&quot;库 → 表&quot;的树展开给你看，写 SQL 就用它自带的查询控制台（会带上&quot;在哪个库执行&quot;的上下文）——<strong>本篇后面练习题的 SQL 既可以在命令行里跑，也可以在 DataGrip 的查询控制台里跑</strong>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>SQL 是什么</td><td>一门操作关系型数据库的编程语言，定义了操作<strong>所有</strong>关系型数据库的<strong>统一标准</strong></td></tr><tr><td>SQL 四大分类</td><td><strong>DDL</strong>（数据定义语言，定义数据库对象：数据库、表、字段）、<strong>DML</strong>（数据操作语言，对表中数据增删改）、<strong>DQL</strong>（数据查询语言，查询表中记录）、<strong>DCL</strong>（数据控制语言，创建用户、控制访问权限）</td></tr><tr><td>DDL 操作数据库的五条语法</td><td><code>show databases;</code>（查所有库）、<code>select database();</code>（查当前库）、<code>use 数据库名;</code>（切换）、<code>create database [if not exists] 库名 [default charset utf8mb4];</code>（创建）、<code>drop database [if exists] 库名;</code>（删除）</td></tr><tr><td>怎么让建库/删库&quot;不报错&quot;</td><td>创建时加 <strong><code>if not exists</code></strong>，删除时加 <strong><code>if exists</code></strong>；已存在/不存在时只给一条 warning</td></tr><tr><td><strong>本机实测（MySQL 9.0.1）</strong></td><td>重复建库 → <code>ERROR 1007 (HY000): Can&#39;t create database &#39;db01&#39;; database exists</code>；删不存在的库 → <code>ERROR 1008 (HY000): Can&#39;t drop database &#39;db_not_exist&#39;; database doesn&#39;t exist</code></td></tr><tr><td>database 与 schema</td><td>语法里的 <code>database</code> 可以换成 <strong><code>schema</code></strong>（如 <code>create schema db01;</code>），效果一样</td></tr><tr><td>MySQL 8 默认字符集</td><td><strong>utf8mb4</strong>，所以 <code>default charset utf8mb4</code> 可以显式写上，也可以省略</td></tr><tr><td>同一台服务器上库名能重复吗</td><td><strong>不能</strong>（重名报 1007）</td></tr><tr><td>命令行客户端的三个痛点</td><td><strong>无提示</strong>、<strong>操作繁琐</strong>、<strong>无历史记录</strong> → 企业里用图形化工具</td></tr><tr><td>DataGrip 是什么</td><td><strong>JetBrains</strong> 旗下的数据库管理工具，官网 <code>https://www.jetbrains.com/zh-cn/datagrip/</code>；连库要填 Host（IP）、Port（端口）、User（用户名）、Password（密码），并<strong>下载驱动</strong></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/40-数据库概述与mysql入门/">上一篇：数据库概述与MySQL入门</a></li><li><a href="/posts/编程学习/javaweb学习笔记/42-ddl表结构-创建与约束/">下一篇：DDL表结构-创建与约束</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li><strong>SQL</strong>：一门操作关系型数据库的编程语言，定义操作<strong>所有</strong>关系型数据库的<strong>统一标准</strong></li><li><strong>四分类</strong>：<strong>DDL</strong>（Data Definition Language，数据定义语言——定义数据库对象：<strong>数据库、表、字段</strong>）、<strong>DML</strong>（Data Manipulation Language，数据操作语言——对表中数据<strong>增删改</strong>）、<strong>DQL</strong>（Data Query Language，数据查询语言——<strong>查询</strong>表中记录）、<strong>DCL</strong>（Data Control Language，数据控制语言——<strong>创建数据库用户、控制访问权限</strong>）</li><li><strong>操作对象区分法</strong>：DDL 动<strong>结构</strong>（库/表/字段），DML 与 DQL 动<strong>内容</strong>（表里的数据/记录）</li><li><strong>DDL-数据库五条</strong>：<code>show databases;</code>、<code>select database();</code>、<code>use 数据库名;</code>、<code>create database [if not exists] 数据库名 [default charset utf8mb4];</code>、<code>drop database [if exists] 数据库名;</code></li><li><strong>顺序</strong>：PPT 总结成&quot;<strong>查询 – 使用 – 创建 – 删除</strong>&quot;</li><li><strong>两个&quot;不报错&quot;参数</strong>：建库加 <strong><code>if not exists</code></strong>（已存在时不报错）、删库加 <strong><code>if exists</code></strong>（不存在时不报错），都只给一条 warning</li><li><strong>本机实测（MySQL 9.0.1）</strong>：重复建库报 <strong><code>ERROR 1007 (HY000): Can&#39;t create database &#39;db01&#39;; database exists</code></strong>；删不存在的库报 <strong><code>ERROR 1008 (HY000): Can&#39;t drop database &#39;db_not_exist&#39;; database doesn&#39;t exist</code></strong></li><li><strong>两个注意点</strong>：① 语法里的 <code>database</code> 可以换成 <strong><code>schema</code></strong>（<code>create schema db01;</code> 效果相同）；② <strong>MySQL 8 默认字符集是 utf8mb4</strong></li><li><strong>同一服务器上库名不能重复</strong>（所以建库前先 <code>show databases</code> 看一眼，或者直接带 <code>if not exists</code>）</li><li><strong>命令行客户端的三个痛点</strong>：<strong>无提示</strong>、<strong>操作繁琐</strong>、<strong>无历史记录</strong>；企业里用<strong>图形化工具</strong>——课程用 <strong>DataGrip</strong>（JetBrains 出品，官网 <code>https://www.jetbrains.com/zh-cn/datagrip/</code>），连库填 <strong>Host / Port / User / Password</strong> 并下载驱动</li></ol><h3 id="二、裸写题" tabindex="-1">二、裸写题 <a class="header-anchor" href="#二、裸写题" aria-label="Permalink to &quot;二、裸写题&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 把服务器上的库&quot;看清楚、切过去&quot;</strong> 连上 MySQL 之后，依次完成三件事：① 列出这台服务器上现有的<strong>所有数据库</strong>；② 显示<strong>当前正在使用</strong>的是哪个数据库；③ 切换到 <code>db01</code> 库，并再确认一次当前库。 （练习文件 <code>test_41_数据库操作.sql</code> 的题目 2-1 处，做完把实际结果抄在注释里。）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：这三件事都是&quot;<strong>库层面</strong>&quot;的操作（还没碰到表），各有一条固定命令；第 ③ 步切完要<strong>再查一次</strong>才能证明切成功了 <strong>二级 · 方法</strong>：列所有库用 <code>show databases</code>；查当前库用 <code>select database()</code>（注意带括号）；切换用 <code>use 库名</code><strong>三级 · 骨架</strong>：<code>＿＿ databases;</code> → <code>select ＿＿();</code> → <code>＿＿ db01;</code> → <code>select ＿＿();</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ① 列出所有数据库</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ② 显示当前数据库</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ③ 切换到 db01 并确认</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db01;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>本机实测（MySQL 9.0.1）的对应输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql&gt; show databases;</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| Database           |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| db01               |</span></span>
<span class="line"><span>| information_schema |</span></span>
<span class="line"><span>| mysql              |</span></span>
<span class="line"><span>| performance_schema |</span></span>
<span class="line"><span>| sys                |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>mysql&gt; select database();</span></span>
<span class="line"><span>+------------+</span></span>
<span class="line"><span>| database() |</span></span>
<span class="line"><span>+------------+</span></span>
<span class="line"><span>| NULL       |</span></span>
<span class="line"><span>+------------+</span></span>
<span class="line"><span>mysql&gt; use db01;</span></span>
<span class="line"><span>Database changed</span></span>
<span class="line"><span>mysql&gt; select database();</span></span>
<span class="line"><span>+------------+</span></span>
<span class="line"><span>| database() |</span></span>
<span class="line"><span>+------------+</span></span>
<span class="line"><span>| db01       |</span></span>
<span class="line"><span>+------------+</span></span></code></pre></div><p>两个细节：① <code>select database()</code> 在前两行返回 <strong>NULL</strong>，说明&quot;连上服务器&quot;不等于&quot;选中了某个库&quot;（连接命令末尾跟一个库名，就等于连上后自动 <code>use</code> 它）；② 后四个 <code>information_schema</code>、<code>mysql</code>、<code>performance_schema</code>、<code>sys</code> 是<strong>系统库</strong>，MySQL 自带，别去动。</p></details></li><li><p>[ ] <strong>2-2 建一个库，再把它删掉（要求都不报错）</strong> 写一组语句：① 创建一个名为 <code>db_test</code> 的数据库，<strong>字符集显式指定为 utf8mb4</strong>，并且<strong>它已经存在时不要报错</strong>；② 列出所有数据库确认它在里面；③ 切过去确认当前库；④ 删除 <code>db_test</code>，<strong>它不存在时不要报错</strong>；⑤ 再列一次确认它没了。 （对应练习文件题目 2-2。）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：①④ 的关键在&quot;<strong>容错参数</strong>&quot;——让语句在对象已存在（或不存在）时安静地跳过而不是报错；②③⑤ 就是 2-1 用过的那几条 <strong>二级 · 方法</strong>：建库 <code>create database [if not exists] 库名 [default charset 字符集];</code>；删库 <code>drop database [if exists] 库名;</code><strong>三级 · 骨架</strong>：<code>create database ＿＿ db_test ＿＿ utf8mb4;</code> … <code>＿＿ database ＿＿ db_test;</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ① 创建库（存在则跳过，显式指定字符集）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_test </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> charset utf8mb4;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ② 确认它在列表里</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ③ 切过去并确认</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_test;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ④ 删除库（不存在则跳过）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">drop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_test;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ⑤ 确认它没了</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span></code></pre></div><p>要点：<code>create database</code> 完整语法是 <code>create database [if not exists] 数据库名 [default charset utf8mb4];</code>——后面的括号里都是<strong>可选部分</strong>，<code>[]</code> 不出现在真正执行的语句里。<code>if not exists</code> / <code>if exists</code> 让&quot;重复建&quot;&quot;删不存在的&quot;都只给 <code>1 warning</code>（见本篇实测表），非常适合写在脚本里反复执行。</p></details></li><li><p>[ ] <strong>2-3 读懂这两条报错，并改到不报错</strong> 同一台服务器上操作时，出现了两条报错：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① ERROR 1007 (HY000): Can&#39;t create database &#39;db_test&#39;; database exists</span></span>
<span class="line"><span>② ERROR 1008 (HY000): Can&#39;t drop database &#39;db_xxx&#39;; database doesn&#39;t exist</span></span></code></pre></div><p>请分别写出：原因是什么、加上哪个关键字后就不报了、改好后的完整语句是什么。 （对应练习文件题目 2-3。）</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：两条报错都在说&quot;你这个对象的状态和你要求的动作冲突了&quot;——一条是&quot;已经有了还让我建&quot;，一条是&quot;根本没有还让我删&quot; <strong>二级 · 方法</strong>：建库语句可以带 <code>if not exists</code>；删库语句可以带 <code>if exists</code><strong>三级 · 骨架</strong>：<code>create database ＿＿ 库名 [default charset utf8mb4];</code> / <code>drop database ＿＿ 库名;</code></p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p>① <strong>原因</strong>：这个库里已经存在一个叫 <code>db_test</code> 的数据库，<code>create database</code> 不做覆盖（这也印证了&quot;同一个服务器上库名不能重复&quot;）；<strong>不报错的写法</strong>：加上 <code>if not exists</code>——</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_test </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> charset utf8mb4;</span></span></code></pre></div><p>② <strong>原因</strong>：服务器上根本没有叫 <code>db_xxx</code> 的库，<code>drop database</code> 找不到对象（注意它<strong>不会</strong>当成&quot;已经删掉了&quot;而放过）；<strong>不报错的写法</strong>：加上 <code>if exists</code>——</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">drop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_xxx;</span></span></code></pre></div><p>加上之后，重复建库、删不存在的库都只返回 <code>Query OK, 0 rows affected, 1 warning (0.00 sec)</code>。**本机实测（MySQL 9.0.1）**的原始报错就是题面这两条，<code>SQL脚本.sql</code> 里最朴素的 <code>create database db03;</code> / <code>drop database db03;</code> 就是会报错的那种写法。</p></details></li></ul><h3 id="三、综合题" tabindex="-1">三、综合题 <a class="header-anchor" href="#三、综合题" aria-label="Permalink to &quot;三、综合题&quot;">​</a></h3><ul><li><p>[ ] <strong>3-1 从命令行到 DataGrip：把一个练习库从零准备出来</strong> 照着课程的做法走一遍完整流程（命令行和图形化工具<strong>都要练</strong>）：</p><ol><li><strong>命令行连上</strong>：用 <code>mysql</code> 客户端连上服务器（用户名 <code>root</code>，密码自己输，别写在命令里）；</li><li><strong>先看有什么</strong>：列出所有数据库，在注释里写下业务库和系统库各是哪些；</li><li><strong>建练习库</strong>：创建一个名为 <code>db_practice</code> 的数据库（字符集显式 utf8mb4，已存在时不报错），再列一次库确认它出现了；</li><li><strong>切过去</strong>：切换到 <code>db_practice</code>，确认当前库；</li><li><strong>在 DataGrip 里也连一份</strong>：打开 DataGrip → Database Explorer 点 <code>+</code> → Data Source → MySQL，Host / Port / User / Password 分别该填什么？对照第 1 步的命令行参数写出来；记得点一次驱动下载；</li><li><strong>在 DataGrip 里验证</strong>：用它的查询控制台执行一次&quot;列出所有数据库&quot;，确认能看到第 3 步建的 <code>db_practice</code>；</li><li><strong>收尾</strong>：删掉 <code>db_practice</code>（不存在时不报错），再列一次库确认没了；</li><li><strong>答两问</strong>：① 命令行连库填的 <code>-h -P -u -p</code> 和 DataGrip 里填的四个框是怎么对应的？② 为什么建库、删库都建议带上 <code>if not exists</code> / <code>if exists</code>？</li></ol><p><strong>涉及知识点</strong></p><table tabindex="0"><thead><tr><th>知识点</th><th>在这里的应用</th></tr></thead><tbody><tr><td>SQL 分类</td><td><code>create</code> / <code>drop</code> / <code>show</code> / <code>use</code> 都属于 <strong>DDL</strong>（作用在&quot;库&quot;这一层）</td></tr><tr><td>五条语法</td><td><code>show databases</code>、<code>select database()</code>、<code>use</code>、<code>create database</code>、<code>drop database</code></td></tr><tr><td>容错参数</td><td><code>if not exists</code> / <code>if exists</code> 让脚本可重复执行</td></tr><tr><td>database 与 schema</td><td>两种写法效果相同</td></tr><tr><td>客户端工具的痛点</td><td>命令行无提示、繁琐、无历史 → DataGrip 补齐</td></tr><tr><td>DataGrip 连接</td><td>Host / Port / User / Password + 下载驱动</td></tr></tbody></table><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：整体是&quot;<strong>连上 → 看现状 → 建库 → 用库 → 换图形化工具再连一遍 → 删库收尾</strong>&quot;；第 5、8 步考的是&quot;命令行参数与图形界面四件套的对应关系&quot; <strong>二级 · 方法</strong>：列库 <code>show databases</code>；建库 <code>create database if not exists 库名 default charset utf8mb4</code>；切库 <code>use 库名</code>；查当前库 <code>select database()</code>；删库 <code>drop database if exists 库名</code>；DataGrip 里点是 <code>+</code> → <code>Data Source</code> → <code>MySQL</code><strong>三级 · 骨架</strong>：<code>create database ＿＿ db_practice ＿＿ utf8mb4;</code> → <code>use ＿＿; select ＿＿();</code> → DataGrip：Host=IP、Port=＿＿、User=＿＿、Password=＿＿</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><ol><li>命令行连接（带字符集参数，避免中文报 1366）：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --default-character-set=utf8mb4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -uroot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span></code></pre></div></li><li>列库（本机实测（MySQL 9.0.1）输出）：<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql&gt; show databases;</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| Database           |</span></span>
<span class="line"><span>+--------------------+</span></span>
<span class="line"><span>| db01               |</span></span>
<span class="line"><span>| information_schema |</span></span>
<span class="line"><span>| mysql              |</span></span>
<span class="line"><span>| performance_schema |</span></span>
<span class="line"><span>| sys                |</span></span>
<span class="line"><span>+--------------------+</span></span></code></pre></div>业务库：<code>db01</code>；系统库：<code>information_schema</code>、<code>mysql</code>、<code>performance_schema</code>、<code>sys</code>。</li><li>建库 + 确认：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_practice </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> charset utf8mb4;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span></code></pre></div></li><li>切库 + 确认：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_practice;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 返回 db_practice</span></span></code></pre></div></li><li>DataGrip 的四个框：<strong>Host</strong> 填数据库服务器 IP（本机就是 <code>localhost</code>）↔ 命令行的 <code>-h</code>；<strong>Port</strong> 填 <code>3306</code> ↔ 命令行的 <code>-P</code>；<strong>User</strong> 填 <code>root</code> ↔ 命令行的 <code>-u</code>；<strong>Password</strong> 填密码 ↔ 命令行的 <code>-p</code>。URL 会自动拼成 <code>jdbc:mysql://localhost:3306</code>；<strong>要点一下 Download 把驱动下下来</strong>，否则连不上。</li><li>DataGrip 查询控制台里执行 <code>show databases;</code>，结果里能看到 <code>db_practice</code>（DataGrip 是把同一条 SQL 发给同一个 DBMS，界面不同而已）。</li><li>删库 + 确认：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">drop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> database</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> exists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_practice;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show databases;</span></span></code></pre></div></li><li>两问： ① 一一对应关系：<code>-h</code>→Host、<code>-P</code>→Port、<code>-u</code>→User、<code>-p</code>→Password（命令行还有 <code>--default-character-set=utf8mb4</code>，DataGrip 一般在驱动配置里带字符集，Windows 下不容易出 1366）； ② 因为 <code>if not exists</code> / <code>if exists</code> 让语句变成<strong>幂等</strong>的——重复执行同一份脚本不会中断（只给一条 warning）。在做练习、写初始化脚本、反复部署时非常实用；不加的话第二次执行就会报 1007 / 1008 把脚本打断。</li></ol></details></li></ul>`,59)])])}const b=t(n,[["render",d]]);export{g as __pageData,b as default};
